package com.knowflow.learning.tutor;
import java.sql.*;
public final class TutorSchema {
 private TutorSchema(){}
 public static boolean exists(Connection c)throws SQLException{try(var rs=c.getMetaData().getTables(c.getCatalog(),c.getSchema(),null,new String[]{"TABLE"})){while(rs.next())if("tutor_session".equalsIgnoreCase(rs.getString("TABLE_NAME")))return true;}return false;}
 public static void migrate(Connection c)throws SQLException{try(var st=c.createStatement()){st.execute("CREATE TABLE IF NOT EXISTS tutor_session (conversation_id BIGINT PRIMARY KEY,owner_id BIGINT NOT NULL,note_id BIGINT NOT NULL,active_mode VARCHAR(20) NOT NULL,revision BIGINT NOT NULL DEFAULT 1,create_time TIMESTAMP(6) NOT NULL,UNIQUE(owner_id,note_id))");}}
 public static void coaching(java.sql.Connection c)throws java.sql.SQLException{try(var st=c.createStatement()){st.execute("CREATE TABLE IF NOT EXISTS tutor_hint_usage (id BIGINT AUTO_INCREMENT PRIMARY KEY,conversation_id BIGINT NOT NULL,owner_id BIGINT NOT NULL,request_id VARCHAR(80) NOT NULL,hint_level INT NOT NULL,state VARCHAR(20) NOT NULL,user_message_id BIGINT,assistant_message_id BIGINT,source_revision BIGINT NOT NULL,created_at TIMESTAMP(6) NOT NULL,UNIQUE(owner_id,request_id))");st.execute("CREATE TABLE IF NOT EXISTS tutor_assessment (id BIGINT AUTO_INCREMENT PRIMARY KEY,conversation_id BIGINT NOT NULL,owner_id BIGINT NOT NULL,request_id VARCHAR(80) NOT NULL,user_message_id BIGINT NOT NULL,assistant_message_id BIGINT,original_text LONGTEXT NOT NULL,topic VARCHAR(200) NOT NULL,knowledge_id BIGINT,previous_id BIGINT,source_revision BIGINT NOT NULL,source_refs LONGTEXT NOT NULL,rubric_version VARCHAR(60) NOT NULL,prompt_version VARCHAR(60) NOT NULL,model_scope VARCHAR(200) NOT NULL,state VARCHAR(20) NOT NULL,result_json LONGTEXT,error_message VARCHAR(500),created_at TIMESTAMP(6) NOT NULL,evaluated_at TIMESTAMP(6),UNIQUE(owner_id,request_id))");st.execute("CREATE TABLE IF NOT EXISTS tutor_micro_session (id BIGINT AUTO_INCREMENT PRIMARY KEY,owner_id BIGINT NOT NULL,note_id BIGINT NOT NULL,conversation_id BIGINT NOT NULL,quiz_id BIGINT NOT NULL,question_index INT NOT NULL,target VARCHAR(3000) NOT NULL,assessment_id BIGINT,request_id VARCHAR(80) NOT NULL,source_revision BIGINT NOT NULL,state VARCHAR(20) NOT NULL,analogy VARCHAR(2000),concept VARCHAR(3000),source_quote VARCHAR(2000),attempt_id BIGINT,draft_answer VARCHAR(10),hint_snapshot VARCHAR(4000),created_at TIMESTAMP(6) NOT NULL,started_at TIMESTAMP(6),completed_at TIMESTAMP(6),error_message VARCHAR(500),UNIQUE(owner_id,request_id))");st.execute("UPDATE tutor_hint_usage SET state='FAILED' WHERE state='GENERATING'");st.execute("UPDATE tutor_assessment SET state='FAILED',error_message='生成被重启中断，原文已保留，请重试' WHERE state='GENERATING'");st.execute("UPDATE tutor_micro_session SET state='FAILED',error_message='生成被重启中断，请重试' WHERE state='GENERATING'");}}
}
